describe('Browser Back Button Navigation', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.clearLocalStorage();
    cy.clearCookies();
  });

  it('should maintain app state when using browser back button from detail page', () => {
    // Navigate to list page and verify initial state
    cy.visit('http://localhost:3000/products');
    cy.get('[data-testid="product-list"]').should('be.visible');
    cy.get('[data-testid="product-item"]').should('have.length.greaterThan', 0);

    // Store initial list state
    cy.get('[data-testid="product-item"]').first().then(($item) => {
      const firstItemText = $item.text();

      // Click on first product to navigate to detail page
      cy.get('[data-testid="product-item"]').first().click();
      cy.url().should('include', '/products/');
      cy.get('[data-testid="product-detail"]').should('be.visible');
      cy.get('[data-testid="product-name"]').should('contain', firstItemText);

      // Use browser back button
      cy.go('back');

      // Verify we're back on list page with preserved state
      cy.url().should('include', '/products');
      cy.get('[data-testid="product-list"]').should('be.visible');
      cy.get('[data-testid="product-item"]').first().should('contain', firstItemText);
      cy.get('[data-testid="product-item"]').should('have.length.greaterThan', 0);
    });
  });

  it('should preserve form data and filters when navigating back', () => {
    // Navigate to products page
    cy.visit('http://localhost:3000/products');

    // Apply filter
    cy.get('[data-testid="filter-category"]').select('Electronics');
    cy.get('[data-testid="apply-filter-btn"]').click();
    cy.get('[data-testid="product-item"]').should('have.length.greaterThan', 0);

    // Verify filter is applied
    cy.get('[data-testid="filter-category"]').should('have.value', 'Electronics');
    cy.get('[data-testid="active-filter-badge"]').should('contain', 'Electronics');

    // Navigate to a product detail
    cy.get('[data-testid="product-item"]').first().click();
    cy.url().should('include', '/products/');
    cy.get('[data-testid="product-detail"]').should('be.visible');

    // Go back
    cy.go('back');

    // Verify filter state is preserved
    cy.url().should('include', '/products');
    cy.get('[data-testid="filter-category"]').should('have.value', 'Electronics');
    cy.get('[data-testid="active-filter-badge"]').should('contain', 'Electronics');
    cy.get('[data-testid="product-item"]').should('have.length.greaterThan', 0);
  });

  it('should handle multiple back navigations without breaking app state', () => {
    // Navigate through multiple pages
    cy.visit('http://localhost:3000/products');
    cy.get('[data-testid="product-list"]').should('be.visible');

    // First navigation
    cy.get('[data-testid="product-item"]').first().click();
    cy.url().should('include', '/products/');
    cy.get('[data-testid="product-detail"]').should('be.visible');

    // Second navigation - go to reviews
    cy.get('[data-testid="product-reviews-link"]').click();
    cy.url().should('include', '/reviews');
    cy.get('[data-testid="reviews-section"]').should('be.visible');

    // First back - should go to product detail
    cy.go('back');
    cy.url().should('include', '/products/');
    cy.get('[data-testid="product-detail"]').should('be.visible');

    // Second back - should go to product list
    cy.go('back');
    cy.url().should('include', '/products');
    cy.get('[data-testid="product-list"]').should('be.visible');

    // Verify app is still functional
    cy.get('[data-testid="product-item"]').should('have.length.greaterThan', 0);
    cy.get('[data-testid="product-item"]').first().click();
    cy.url().should('include', '/products/');
    cy.get('[data-testid="product-detail"]').should('be.visible');
  });

  it('should handle back button on page with unsaved changes gracefully', () => {
    // Navigate to edit page
    cy.visit('http://localhost:3000/products');
    cy.get('[data-testid="product-item"]').first().click();
    cy.get('[data-testid="edit-product-btn"]').click();
    cy.url().should('include', '/edit');
    cy.get('[data-testid="product-form"]').should('be.visible');

    // Make changes to form
    cy.get('[data-testid="product-name-input"]').clear().type('Updated Product Name');
    cy.get('[data-testid="form-dirty-indicator"]').should('be.visible');

    // Attempt back navigation
    cy.go('back');

    // Verify warning dialog appears or form state is preserved
    cy.get('[data-testid="unsaved-changes-dialog"]').should('exist');
    cy.get('[data-testid="discard-changes-btn"]').click();

    // Verify navigation completes
    cy.url().should('include', '/products/');
    cy.get('[data-testid="product-detail"]').should('be.visible');
  });

  it('should not break app state when back button is used rapidly', () => {
    cy.visit('http://localhost:3000/products');
    cy.get('[data-testid="product-list"]').should('be.visible');

    // Navigate to first product
    cy.get('[data-testid="product-item"]').first().click();
    cy.url().should('include', '/products/');

    // Navigate to second product
    cy.get('[data-testid="back-to-list-btn"]').click();
    cy.get('[data-testid="product-item"]').eq(1).click();
    cy.url().should('include', '/products/');

    // Rapid back navigation
    cy.go('back');
    cy.go('back');

    // Verify app state is intact
    cy.url().should('include', '/products');
    cy.get('[data-testid="product-list"]').should('be.visible');
    cy.get('[data-testid="product-item"]').should('have.length.greaterThan', 0);

    // Verify we can still interact with the app
    cy.get('[data-testid="product-item"]').first().click();
    cy.url().should('include', '/products/');
    cy.get('[data-testid="product-detail"]').should('be.visible');
  });
});
